#!/usr/bin/env python3
"""Build local-help.html and ramps-home-access.html from data/ (no hand-edited output)."""
import html,json
from pathlib import Path
from build_mobility_routes import STATES,TERRITORIES
from site_parts import URGENT,SIDE_HELP,RELAY,ABOUT_LINK,guides,icon
ROOT=Path(__file__).resolve().parents[1]
E=lambda s:html.escape(str(s),quote=True)
NAV='<nav aria-label="Main"><a href="./">Home</a><a href="mobility-rights.html">Find your next step</a><a href="local-help.html">Local help &amp; programs</a><a href="know-your-rights.html">Know your rights</a><a href="ramps-home-access.html">Ramps &amp; home access</a><a href="disability-advocacy.html">Advocacy</a><a href="mobility-independence.html">Repair &amp; adapt</a></nav>'
FOOT='<footer><p>Created and maintained by Travis Vought. <a href="mailto:travis@vethomeguard.org">Corrections</a> · <a href="./">Home</a> · '+ABOUT_LINK+'</p><p>Program details come from the programs’ own published pages, each with the date it was checked. This is general information, not legal or medical advice, and it does not decide eligibility. Nothing you choose here is saved or sent.</p></footer>'
HEAD='<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">\n<title>{t} | Mobility Talk</title><meta name="description" content="{d}"><link rel="stylesheet" href="assets/site.css"></head>\n<body><a class="skip" href="#main">Skip to main content</a>\n'
def local_help():
    opts='<option value="">Choose your state</option>'+''.join(f'<option value="{c}">{E(n)}</option>' for c,n in sorted(STATES.items(),key=lambda x:x[1]))+'<optgroup label="U.S. territories">'+''.join(f'<option value="{c}">{E(n)}</option>' for c,n in sorted(TERRITORIES.items(),key=lambda x:x[1]))+'</optgroup>'
    J=lambda o:json.dumps(o,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')
    g=guides()
    return HEAD.replace('<link rel="stylesheet" href="assets/site.css">','<link rel="stylesheet" href="assets/vendor/leaflet.css"><link rel="stylesheet" href="assets/site.css">').format(t='Local help and programs',d='Find disability programs by state and county: benefits, health coverage, equipment, ramps, rides, in-home help, work, vision and hearing, and your rights.')+f'''<header>{NAV}<small>LOCAL HELP · EVERY STATE, D.C. AND U.S. TERRITORIES</small><h1>Find a program near you.</h1><!--lede--><!--/lede--></header>
<main id="main"><section class="panel"><form id="filters" role="search" aria-label="Find local help"><h2 class="needs-title">1. Choose your state</h2><div class="filters"><div><label for="f-state">State or territory</label><select id="f-state">{opts}</select></div><div><label for="f-county">County (optional)</label><select id="f-county"><option value="">All counties</option></select></div></div><h2 class="needs-title" id="needs-title">2. What do you need?</h2><div id="needs" class="needs" role="group" aria-labelledby="needs-title"></div><h2 class="needs-title">3. Narrow it down (optional)</h2><div class="filters"><div><label for="f-cat">Type of help</label><select id="f-cat"><option value="">All types</option></select></div><div><label for="f-aud">Who is it for?</label><select id="f-aud"><option value="">Any disability</option></select></div><div><label for="f-q">Search</label><input id="f-q" type="search" placeholder="ramp, wheelchair, Medicaid…" autocomplete="off"></div></div></form><p class="tools"><button type="button" id="f-clear" class="secondary">Clear filters</button> <button type="button" id="f-copy" class="secondary">Copy link to this list</button> <button type="button" id="f-print" class="secondary">Print this list</button></p><p class="status" id="status" role="status" aria-live="polite"></p>{RELAY}</section>
<noscript><p>This directory needs JavaScript. Without it, <a href="states/index.html">browse every state as a plain list</a>, use the <a href="https://guide.vethomeguard.org/">Veteran Resource Guide</a> or read the data file <a href="data/local-programs.json">local-programs.json</a>.</p></noscript>
<section id="statemap" class="panel statemap" aria-labelledby="map-h" hidden><h2 id="map-h">Map of resources</h2><p id="map-summary" class="lead"></p><p class="map-tools"><button type="button" id="map-locate">Use my location</button> <button type="button" id="map-back" class="secondary" hidden>See all states</button></p><p id="map-status" class="status" role="status" aria-live="polite"></p><div class="mapbody"><div class="mapcol"><div id="map-wrap" class="map-wrap" role="region" aria-label="Map of the United States. The same states and territories are listed next to the map."></div><p class="small">Selecting a county adds its local help to the list below; you can also choose a county in the filters above. Your location, if you share it, stays on your device. The map pictures come from OpenStreetMap, which sees which area you look at. <a href="privacy.html#map">Privacy</a></p></div><div class="maplist"><h3 id="map-list-h">On the map</h3><ul id="map-list" class="maphits"></ul></div></div></section><nav id="jump" class="jump" aria-label="Jump to a type of help" hidden></nav>
<section aria-labelledby="results-h"><h2 id="results-h">Programs and services</h2><div id="results"></div></section>
<section class="panel rtr"><h2>Right to repair. Right to modify.</h2><p>These programs help now. Laws that give owners and independent technicians access to parts, tools and software, and the freedom to modify equipment, help everyone. <a href="mobility-independence.html#right-to-repair">Learn about right to repair and right to modify</a> or <a href="disability-advocacy.html">ask lawmakers to act</a>.</p></section>
<section class="panel" id="locators"><h2>Every state has these. Find yours.</h2><p>If your state is not fully listed above, these national directories cover all 50 states and D.C.</p><ul><li><a href="https://www.at3center.net/" rel="noopener">AT3 Center</a>: find your state assistive technology program (equipment loans, demos, financing and reuse).</li><li><a href="https://www.ilru.org/projects/cil-net/cil-center-and-association-directory" rel="noopener">ILRU directory of Centers for Independent Living</a>: choose your state.</li><li><a href="https://www.ndrn.org/about/ndrn-member-agencies/" rel="noopener">NDRN member agencies</a>: your state’s Protection and Advocacy agency for disability rights.</li><li><a href="https://eldercare.acl.gov/" rel="noopener">Eldercare Locator</a>: local aging and disability help.</li><li><a href="https://www.va.gov/housing-assistance/disability-housing-grants/" rel="noopener">VA disability housing grants</a>: SAH, SHA and TRA.</li></ul></section>
<section><p>Looking for aging services, nursing-home resources or benefits help? Open the <a id="guide-link" href="https://guide.vethomeguard.org/">Veteran Resource Guide</a> for this state.</p></section><section><p>Want something to hand to a neighbor, client or family member? <a id="handout-link" href="handout.html">Print a help list for this state</a> with phone numbers for the main programs.</p></section>{SIDE_HELP}</main>{FOOT}
<script type="application/json" id="state-data">{J({**STATES,**TERRITORIES})}</script><script type="application/json" id="territory-data">{J(sorted(TERRITORIES))}</script><script type="application/json" id="guide-data">{J({'results_order':g['results_order'],'guides':g['guides']})}</script><script src="assets/vendor/leaflet.js"></script><script src="assets/help-map.js"></script><script src="assets/local-help.js"></script></body></html>
'''
# Header drawing for the ramps guide (November 24, 2026): a wheelchair user rolling up a ramp with a handrail to a door.
# Decorative and drawn for this site; it shows no measurements, and it is hidden on narrow screens and in print.
RAMP_ART='<svg class="hero-art" viewBox="0 44 260 112" width="260" height="112" aria-hidden="true" focusable="false"><path d="M12 150L186 120H252V150z" fill="#fff" fill-opacity=".1"/><g fill="none" stroke="#e7cc88" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M6 150H254"/><path d="M12 150L186 120H252"/><path d="M17.2 115.1L186.0 86.0H206"/><path d="M22.4 114.2L22.4 148.2"/><path d="M64.2 107.0L64.2 141.0"/><path d="M180.8 86.9L180.8 120.9"/><path d="M206 120V54h40v66"/><path d="M212 120V62h28v58"/><path d="M233 95h.01"/></g><g transform="translate(99.3 116.2) rotate(-9.8)" fill="none" stroke="#fff" stroke-width="4.2" stroke-linecap="round" stroke-linejoin="round"><path d="M15.2 -7.6A17 17 0 1 1 -2 -16.9"/><circle cx="21.5" cy="-40.5" r="6.4" fill="#fff" stroke="none"/><path d="M-1 -8L14 -31"/><path d="M12 -27L-1 -22L-12 -12"/><path d="M-1 -8H20L27 8"/></g></svg>'
def checklist(key,c):
    secs=''.join(f'<h3 class="check-h" id="{E(key)}-{n}">{E(s["title"])}</h3><ul class="steps">'+''.join(f'<li>{E(i["text"])} <span class="meta">({E(i["responsible"])})</span></li>' for i in s['items'])+'</ul>' for n,s in enumerate(c['sections'],1))
    # the checklist's parts, in order, as numbered steps that jump to each part (the data lists them in the order programs ask)
    flow=(f'<ol class="stepper row" role="list" style="--n:{len(c["sections"])}" aria-label="Steps at a glance">'
          +''.join(f'<li><a class="st" href="#{E(key)}-{n}">{E(s["title"])}</a></li>' for n,s in enumerate(c['sections'],1))+'</ol>')
    sub=c['submit'];srcs=' · '.join(f'<a href="{E(u)}" rel="noopener">{E(u.split("//")[1].split("/")[0])}</a>' for u in c['sources'])
    return f'<details id="{E(key)}"><summary>{E(c["title"])}</summary>{flow}{secs}<p><strong>Where to submit:</strong> {E(sub["text"])} <a href="{E(sub["url"])}" rel="noopener">{E(sub["label"])}</a></p><p><strong>After you submit:</strong> {E(c["followUp"])}</p><p class="small">Checked {E(c["reviewedOn"])}. Sources: {srcs}</p></details>'
def ramps():
    cl=json.loads((ROOT/'data/home-access-checklists.json').read_text())
    fix=lambda s:s.replace("VHG's navigator",'this website').replace('VHG’s navigator','this website').replace('—not to VHG','—not through this website').replace(', not for VHG',', not for this website').replace(', not to VHG',', not through this website')
    for c in cl.values():
        c['sections']=[{**s,'items':[{**i,'text':fix(i['text'])} for i in s['items']]} for s in c['sections']]
        c['submit']['text']=fix(c['submit']['text']);c['followUp']=fix(c['followUp'])
    routes=[('veterans','For veterans','VA grants for ramps and adapted homes','HISA pays for medically needed changes such as ramps and bathroom access. SAH and SHA grants adapt or build a home for veterans with qualifying service-connected disabilities. TRA helps while staying with family.','local-help.html?category=veterans','Find your county veterans office'),
    ('funding','Coverage','Medicaid and waiver home modifications','Home and community-based waivers can pay for ramps, lifts, widened doors and bathroom changes when they are in an approved service plan. Ask before any work begins.','local-help.html?category=funding','Find waiver and coverage routes'),
    ('dd_board','Developmental disabilities','County DD boards and DD waivers','Every state has an agency, regional center or county board that decides eligibility, coordinates services and manages waiver funding for equipment and home or vehicle changes.','local-help.html?category=dd_board','Find your DD agency'),
    ('independent_living','Community','Independent living centers','Disability-led centers often know local ramp builders, loan closets and volunteer groups, and can help you apply for funding.','local-help.html?category=independent_living','Find an independent living center'),
    ('ramps_home','Ramps &amp; repairs','Ramp loans and home repair programs','Some states lend portable ramps or fund accessibility modifications. USDA rural home repair loans and grants can help eligible low-income homeowners.','local-help.html?category=ramps_home','See ramp and home programs'),
    ('equipment','Equipment','Try before you buy','Assistive technology programs lend, demonstrate, finance and reuse equipment, and can help you decide what you need before you pay.','local-help.html?category=equipment','Find equipment programs')]
    cards=''.join(f'<article>{icon(k,"hic")}<p class="label">{a}</p><h3>{b}</h3><p>{E(c).replace("&amp;amp;","&amp;")}</p><a class="button" href="{d}">{e}</a></article>' for k,a,b,c,d,e in routes)
    return HEAD.format(t='Ramps, home modification and accessible housing',d='Who pays for or provides ramps and home modifications, plus step-by-step preparation checklists for VA grants and Ohio waiver modifications.')+f'''<header class="has-art">{NAV}<small>RAMPS · HOME MODIFICATION · ACCESSIBLE HOUSING</small>{RAMP_ART}<h1>Get a ramp.<br>Make home work.</h1><!--lede--><!--/lede--></header>
<main id="main"><section><h2>Six routes to try</h2><div class="route">{cards}</div></section>
<section class="panel"><h2>Before you spend anything</h2><ul class="iconlist"><li>{icon('chat_q')}<span>Ask the program whether work must be approved <em>before</em> it starts. Some will not reimburse completed work.</span></li><li>{icon('document')}<span>Get written, itemized quotes with permits and inspections included.</span></li><li>{icon('camera')}<span>Take photos of the area before any changes.</span></li><li>{icon('lock')}<span>Keep copies of records privately. Do not send medical records or claim numbers through this website.</span></li></ul></section>
<section><h2>Preparation checklists</h2><p>These list what the official programs ask for, in order. They are reminders, not applications. Your identifying details go only on the official forms.</p>{''.join(checklist(k,c) for k,c in cl.items())}</section>
<section class="panel rtr"><h2>Right to repair. Right to modify.</h2><p>Home and equipment changes should not wait on one vendor. <a href="mobility-independence.html#right-to-repair">See where right to repair and right to modify stand</a>.</p></section><section><p>Need a ramp or repair and cannot get coverage? <a href="disability-advocacy.html">Ask lawmakers for change</a> or <a href="mobility-rights.html">find your next step by state and problem</a>.</p></section></main>{FOOT}</body></html>
'''
def outputs(): return {'local-help.html':local_help(),'ramps-home-access.html':ramps()}
if __name__=='__main__':
    for p,t in outputs().items():(ROOT/p).write_text(t)
    print('Built local help directory and ramps guide.')
